class Solution { public:int totalStrength(vector<int>& strength){const long long mod=1000000007;int n=strength.size();vector<int> left(n),right(n),stack;for(int i=0;i<n;++i){while(!stack.empty()&&strength[stack.back()]>=strength[i])stack.pop_back();left[i]=stack.empty()?-1:stack.back();stack.push_back(i);}stack.clear();for(int i=n-1;i>=0;--i){while(!stack.empty()&&strength[stack.back()]>strength[i])stack.pop_back();right[i]=stack.empty()?n:stack.back();stack.push_back(i);}vector<long long> pre(n+1),pp(n+2);for(int i=0;i<n;++i)pre[i+1]=(pre[i]+strength[i])%mod;for(int i=0;i<=n;++i)pp[i+1]=(pp[i]+pre[i])%mod;long long answer=0;for(int i=0;i<n;++i){long long positive=(i-left[i])*(pp[right[i]+1]-pp[i+1]+mod)%mod,negative=(right[i]-i)*(pp[i+1]-pp[left[i]+1]+mod)%mod,ranges=(positive-negative+mod)%mod;answer=(answer+strength[i]*ranges)%mod;}return answer;} };
